<template>
  <ContentWrap class="shop-panel">
    <div class="section-head"><div><h3>{{ tt('shop.title') }}</h3><span class="sub-text">{{ tt('shop.description') }}</span></div><el-button @click="load" :loading="loading">{{ tt('common.refresh') }}</el-button></div>
    <el-alert v-if="!loading && !capabilities?.configured" :title="tt('shop.notConfigured')" type="warning" :closable="false" />
    <el-alert v-else-if="capabilities && !capabilities.publishingConfigured" :title="tt('shop.publishingNotConfigured')" type="info" :closable="false" />
    <el-alert v-if="error" :title="error" type="error" :closable="false" />
    <section class="accounts"><div class="section-head"><strong>{{ tt('shop.account') }}</strong><div><el-button v-hasPermi="['tk:tiktok-shop-account:authorize']" type="primary" plain @click="connect">{{ tt('shop.connect') }}</el-button><el-button @click="loadAccounts">{{ tt('shop.refreshAccounts') }}</el-button></div></div><el-table :data="accounts" size="small"><el-table-column prop="id" label="ID" width="90" /><el-table-column :label="tt('shop.account')"><template #default="{ row }">{{ row.displayName || row.username || '-' }}</template></el-table-column><el-table-column prop="authStatus" :label="tt('common.status')" /><el-table-column width="130"><template #default="{ row }"><el-button link type="danger" @click="disconnect(row)">{{ tt('shop.disconnect') }}</el-button></template></el-table-column></el-table></section>
    <el-divider />
    <el-form v-if="selectedAccount" label-width="130px" class="shop-form">
      <el-form-item :label="tt('shop.account')"><el-select v-model="accountId" @change="resetDependent"><el-option v-for="account in accounts" :key="account.id" :label="`${account.displayName || account.username || 'Account'} (#${account.id})`" :value="account.id" /></el-select></el-form-item>
      <el-form-item :label="tt('shop.titleLabel')"><el-input v-model="form.title" type="textarea" maxlength="2200" show-word-limit @input="invalidate" /></el-form-item>
      <el-form-item :label="tt('shop.anchorLabel')"><el-input v-model="form.productLinkTitle" maxlength="29" @input="invalidate" /><span class="sub-text">{{ tt('shop.anchorHint') }}</span></el-form-item>
      <el-form-item :label="tt('shop.aiGenerated')"><el-checkbox v-model="form.isAiGenerated" @change="invalidate">{{ tt('shop.aiGenerated') }}</el-checkbox></el-form-item>
      <el-form-item :label="tt('shop.selectVideo')"><el-select v-model="mediaMode" @change="resetDependent"><el-option value="generated" :label="tt('shop.selectVideo')" /><el-option value="upload" :label="tt('shop.uploadVideo')" /></el-select><el-select v-if="mediaMode === 'generated'" v-model="form.generationTaskId" @change="invalidate" class="ml-10"><el-option v-for="video in generatedVideos" :key="video.id" :value="video.id" :label="`${video.title || 'Video'} (#${video.id})`" /></el-select><input v-else type="file" accept="video/mp4,video/quicktime,video/webm" @change="upload" /><el-progress v-if="uploading" :percentage="uploadPercent" /><el-button v-if="uploading" @click="cancelUpload">{{ tt('shop.cancelUpload') }}</el-button></el-form-item>
      <TiktokShopProductPicker :account-id="accountId" :disabled="!capabilities?.publishingConfigured" @select="selectProduct" @changed="invalidate" />
      <el-button type="primary" :loading="creating" :disabled="!capabilities?.publishingConfigured" @click="createTask">{{ tt('shop.create') }}</el-button>
    </el-form>
    <TiktokShopPublishConfirm :task="activeTask" :account="selectedAccount" :submitting="confirming" :submitted="submitted" @submit="confirmTask" />
    <section class="history"><div class="section-head"><strong>{{ tt('shop.history') }}</strong><el-button @click="loadHistory">{{ tt('shop.refreshHistory') }}</el-button></div><el-table :data="history" size="small" @row-click="selectHistory"><el-table-column prop="id" label="ID" width="80" /><el-table-column prop="stage" :label="tt('common.status')" /><el-table-column prop="title" :label="tt('shop.titleLabel')" min-width="160" /><el-table-column prop="updateTime" label="Updated" /></el-table></section>
    <el-alert v-if="activeTask?.stage === 'RECOVERY_REQUIRED'" :title="`${tt('shop.recovery')}${activeTask.requestId ? ` ${tt('shop.requestId')}: ${activeTask.requestId}` : ''}`" type="warning" :closable="false" />
  </ContentWrap>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { ElMessageBox } from 'element-plus'
import { TiktokShopApi, type ShopAccount, type ShopCapabilities, type ShopCreate, type ShopProduct, type ShopTask } from '@/api/tk/tiktokShop'
import { TkGenerationApi } from '@/api/tk/generation'
import { createShopPoller, createShopRevision, createShopSubmitter, validateShopForm } from './tiktokShopBehavior'
import { createShopUpload } from '@/utils/tiktokShopUpload'
import TiktokShopProductPicker from './TiktokShopProductPicker.vue'
import TiktokShopPublishConfirm from './TiktokShopPublishConfirm.vue'
import { useTkI18n } from '@/hooks/web/useTkI18n'
import { hasPermission } from '@/directives/permission/hasPermi'
const { tt } = useTkI18n(), capabilities = ref<ShopCapabilities>(), accounts = ref<ShopAccount[]>([]), error = ref(''), loading = ref(false)
const accountId = ref<number>(), mediaMode = ref<'generated' | 'upload'>('generated'), generatedVideos = ref<any[]>([]), history = ref<ShopTask[]>([]), activeTask = ref<ShopTask>(), creating = ref(false), confirming = ref(false), submitted = ref(false), uploadPercent = ref(0), uploading = ref(false)
const form = reactive<Partial<ShopCreate>>({ title: '', productLinkTitle: '', productSource: 'SHOWCASE', isAiGenerated: true })
let uploadHandle: ReturnType<typeof createShopUpload> | undefined, popup: Window | undefined, oauthSession: number | undefined, oauthTimer: number | undefined
const revision = createShopRevision(), selectedAccount = computed(() => accounts.value.find((account) => account.id === accountId.value))
const submitter = createShopSubmitter({ create: (data) => TiktokShopApi.create(data), confirm: (id, data) => TiktokShopApi.confirm(id, data), get: (id) => TiktokShopApi.get(id) })
const poller = createShopPoller(async () => { if (!activeTask.value || ['SUCCESS', 'FAILED', 'RECOVERY_REQUIRED'].includes(activeTask.value.stage)) return false; activeTask.value = await TiktokShopApi.get(activeTask.value.id); return !['SUCCESS', 'FAILED', 'RECOVERY_REQUIRED'].includes(activeTask.value.stage) }, () => { error.value = tt('shop.operationFailed') }, { set: window.setTimeout, clear: window.clearTimeout })
async function load() { loading.value = true; error.value = ''; try { capabilities.value = await TiktokShopApi.capabilities(); await loadAccounts(); await loadHistory(); if (hasPermission(['tk:generation:query'])) generatedVideos.value = (await TkGenerationApi.getGenerationPage({ pageNo: 1, pageSize: 20, status: 'SUCCESS' })).list || [] } catch (reason) { error.value = reason instanceof Error ? reason.message : tt('shop.capabilityFailed') } finally { loading.value = false } }
async function loadAccounts() { accounts.value = await TiktokShopApi.accounts(); if (!accountId.value) accountId.value = accounts.value[0]?.id }
async function loadHistory() { const page = await TiktokShopApi.tasks({ pageNo: 1, pageSize: 20 }); history.value = page.list || [] }
async function connect() { const origin = capabilities.value?.callbackOrigin; if (!origin || !/^https:\/\/[^/]+$/i.test(origin)) { error.value = tt('shop.invalidCapability'); return }; popup = window.open('about:blank', 'tiktok-shop-auth', 'width=520,height=720') || undefined; if (!popup) { error.value = tt('shop.popupBlocked'); return }; try { const session = await TiktokShopApi.authorize(); oauthSession = session.sessionId; popup.location.href = session.authorizationUrl; oauthTimer = window.setTimeout(() => { window.removeEventListener('message', onOAuth); popup?.close(); popup = undefined }, 5 * 60_000) } catch (reason) { popup.close(); error.value = reason instanceof Error ? reason.message : tt('shop.authorizationFailed') } }
function onOAuth(event: MessageEvent) { if (!popup || !oauthSession || event.origin !== capabilities.value?.callbackOrigin || event.source !== popup || event.data?.type !== 'tiktok-shop-auth' || event.data.sessionId !== oauthSession) return; window.removeEventListener('message', onOAuth); if (oauthTimer) window.clearTimeout(oauthTimer); popup.close(); popup = undefined; if (event.data.status === 'SUCCESS') void loadAccounts(); else error.value = tt('shop.authorizationFailed') }
async function disconnect(account: ShopAccount) { await ElMessageBox.confirm(tt('shop.disconnectConfirm'), tt('shop.disconnect')); await TiktokShopApi.disconnect(account.id); await loadAccounts() }
function resetDependent() { revision.invalidate(); form.productId = undefined; form.selectionProof = undefined; form.generationTaskId = mediaMode.value === 'generated' ? undefined : form.generationTaskId; form.mediaId = undefined; activeTask.value = undefined; submitted.value = false }
function invalidate() { activeTask.value = undefined; submitted.value = false }
function selectProduct(product: ShopProduct, source: 'SHOP' | 'SHOWCASE') { form.productId = product.id; form.productSource = source; form.selectionProof = product.selectionProof; invalidate() }
async function upload(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file || !capabilities.value) return; if (file.size > capabilities.value.maxVideoBytes) { error.value = tt('shop.videoTooLarge'); return }; uploadHandle = createShopUpload(file, (percent) => { uploadPercent.value = percent }); uploading.value = true; try { const media = await uploadHandle.result; form.mediaId = media.id; form.generationTaskId = undefined; invalidate() } catch (reason) { error.value = reason instanceof Error ? reason.message : tt('shop.operationFailed') } finally { uploading.value = false; uploadHandle = undefined } }
function cancelUpload() { uploadHandle?.cancel() }
async function createTask() { const payload = { ...form, accountId: accountId.value } as Omit<ShopCreate, 'idempotencyKey'>; const invalid = validateShopForm(payload); if (invalid) { error.value = tt(invalid); return }; creating.value = true; try { activeTask.value = await submitter.create(payload); poller.start(); await loadHistory() } catch (reason) { error.value = reason instanceof Error ? reason.message : tt('shop.operationFailed') } finally { creating.value = false } }
async function confirmTask() { if (!activeTask.value || confirming.value || submitted.value) return; confirming.value = true; try { activeTask.value = await submitter.confirm(activeTask.value); submitted.value = true; poller.start(); await loadHistory() } catch { try { activeTask.value = await TiktokShopApi.get(activeTask.value.id) } catch { error.value = tt('shop.recovery') } } finally { confirming.value = false } }
async function selectHistory(task: ShopTask) { const requestRevision = revision.next(); const fresh = await TiktokShopApi.get(task.id); if (revision.current(requestRevision)) activeTask.value = fresh }
onMounted(() => { window.addEventListener('message', onOAuth); void load() })
onBeforeUnmount(() => { window.removeEventListener('message', onOAuth); poller.stop(); uploadHandle?.cancel(); if (oauthTimer) window.clearTimeout(oauthTimer); popup?.close() })
</script>
<style scoped>.shop-panel { min-height: 400px; }.section-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }.accounts, .history { margin-top: 16px; }.shop-form :deep(.el-select) { min-width: 260px; }.ml-10 { margin-left: 10px; }.sub-text { color: var(--el-text-color-secondary); font-size: 12px; }</style>
